# Create HuggingFace API client that connects to our Phase 1 app
hf_api_ts = '''import { APIError, handleAPIError } from './utils'

// Types for HF Spaces API responses
export interface HFModelResponse {
  generated_text?: string
  label?: string
  score?: number
  translation_text?: string
  summary_text?: string
  error?: string
}

export interface HFProcessingOptions {
  model?: string
  maxTokens?: number
  temperature?: number
  topP?: number
  topK?: number
  repetitionPenalty?: number
  maxTime?: number
}

export interface HFImageProcessingOptions {
  model?: string
  task?: 'image-classification' | 'object-detection' | 'image-segmentation'
}

export interface HFHealthStatus {
  status: 'healthy' | 'degraded' | 'unhealthy'
  services: {
    api: boolean
    database: boolean
    models: boolean
  }
  uptime: number
  version: string
  timestamp: string
}

class HuggingFaceAPI {
  private baseURL: string
  private apiKey?: string

  constructor() {
    // This connects to our Phase 1 HF Spaces app
    this.baseURL = process.env.NEXT_PUBLIC_HF_SPACES_URL || 'https://your-space.hf.space'
    this.apiKey = process.env.NEXT_PUBLIC_HF_API_KEY
  }

  private async makeRequest<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<T> {
    const url = `${this.baseURL}${endpoint}`

    const headers: HeadersInit = {
      'Content-Type': 'application/json',
      ...options.headers,
    }

    // Add API key if available
    if (this.apiKey) {
      headers['Authorization'] = `Bearer ${this.apiKey}`
    }

    try {
      const response = await fetch(url, {
        ...options,
        headers,
        // Add timeout for mobile networks
        signal: AbortSignal.timeout(30000)
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        throw new APIError(
          errorData.error || `HTTP ${response.status}: ${response.statusText}`,
          response.status,
          errorData.code
        )
      }

      return await response.json()
    } catch (error) {
      if (error instanceof APIError) {
        throw error
      }

      // Handle network errors, timeouts, etc.
      throw handleAPIError(error)
    }
  }

  // Text processing (connects to our HF Spaces /predict endpoint)
  async processText(
    text: string,
    options: HFProcessingOptions = {}
  ): Promise<HFModelResponse> {
    return this.makeRequest<HFModelResponse>('/predict', {
      method: 'POST',
      body: JSON.stringify({
        inputs: text,
        parameters: {
          max_new_tokens: options.maxTokens || 150,
          temperature: options.temperature || 0.7,
          top_p: options.topP || 0.9,
          top_k: options.topK || 50,
          repetition_penalty: options.repetitionPenalty || 1.0,
          max_time: options.maxTime || 30.0,
          model: options.model || 'gpt2'
        }
      })
    })
  }

  // Sentiment analysis
  async analyzeSentiment(text: string): Promise<HFModelResponse> {
    return this.makeRequest<HFModelResponse>('/api/sentiment', {
      method: 'POST',
      body: JSON.stringify({
        text,
        model: 'distilbert-base-uncased-finetuned-sst-2-english'
      })
    })
  }

  // Text summarization
  async summarizeText(
    text: string,
    maxLength?: number,
    minLength?: number
  ): Promise<HFModelResponse> {
    return this.makeRequest<HFModelResponse>('/api/summarize', {
      method: 'POST',
      body: JSON.stringify({
        text,
        parameters: {
          max_length: maxLength || 150,
          min_length: minLength || 30,
          do_sample: false
        }
      })
    })
  }

  // Translation
  async translateText(
    text: string,
    sourceLanguage: string = 'en',
    targetLanguage: string = 'fr'
  ): Promise<HFModelResponse> {
    return this.makeRequest<HFModelResponse>('/api/translate', {
      method: 'POST',
      body: JSON.stringify({
        text,
        source_language: sourceLanguage,
        target_language: targetLanguage
      })
    })
  }

  // Image processing
  async processImage(
    imageFile: File,
    options: HFImageProcessingOptions = {}
  ): Promise<HFModelResponse[]> {
    const formData = new FormData()
    formData.append('file', imageFile)
    formData.append('task', options.task || 'image-classification')
    formData.append('model', options.model || 'google/vit-base-patch16-224')

    return this.makeRequest<HFModelResponse[]>('/api/image', {
      method: 'POST',
      body: formData,
      headers: {} // Let browser set Content-Type for FormData
    })
  }

  // Batch processing (for multiple requests)
  async processBatch(
    requests: Array<{
      text: string
      task: 'generation' | 'sentiment' | 'summarization' | 'translation'
      options?: HFProcessingOptions
    }>
  ): Promise<HFModelResponse[]> {
    return this.makeRequest<HFModelResponse[]>('/api/batch', {
      method: 'POST',
      body: JSON.stringify({
        requests
      })
    })
  }

  // Get available models
  async getAvailableModels(): Promise<string[]> {
    return this.makeRequest<string[]>('/api/models')
  }

  // Health check (connects to our HF Spaces health endpoint)
  async getHealth(): Promise<HFHealthStatus> {
    return this.makeRequest<HFHealthStatus>('/health')
  }

  // Usage statistics
  async getUsageStats(userId: string): Promise<{
    requests_today: number
    requests_month: number
    tokens_used: number
    cost_today: number
    cost_month: number
  }> {
    return this.makeRequest('/api/usage', {
      method: 'POST',
      body: JSON.stringify({ user_id: userId })
    })
  }

  // Revenue tracking (connects to our revenue engine)
  async trackRevenue(
    userId: string,
    amount: number,
    eventType: string,
    metadata?: any
  ): Promise<{ success: boolean; event_id: string }> {
    return this.makeRequest('/api/revenue', {
      method: 'POST',
      body: JSON.stringify({
        user_id: userId,
        amount,
        event_type: eventType,
        metadata
      })
    })
  }

  // Get model performance metrics
  async getModelMetrics(model: string): Promise<{
    avg_response_time: number
    success_rate: number
    total_requests: number
    last_24h_requests: number
  }> {
    return this.makeRequest(`/api/metrics/${encodeURIComponent(model)}`)
  }
}

