# Create API routes and webhooks for Stripe and other integrations
stripe_webhook_ts = '''import { NextRequest, NextResponse } from 'next/server'
import Stripe from 'stripe'
import { createServerClient } from '@/lib/supabase'
import { trackRevenueEvent } from '@/lib/supabase'

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2023-10-16'
})

const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET!

export async function POST(request: NextRequest) {
  try {
    const body = await request.text()
    const signature = request.headers.get('stripe-signature')

    if (!signature) {
      return NextResponse.json(
        { error: 'Missing stripe signature' },
        { status: 400 }
      )
    }

    // Verify the webhook signature
    let event: Stripe.Event
    try {
      event = stripe.webhooks.constructEvent(body, signature, webhookSecret)
    } catch (err) {
      console.error('Webhook signature verification failed:', err)
      return NextResponse.json(
        { error: 'Invalid signature' },
        { status: 400 }
      )
    }

    // Handle different event types
    switch (event.type) {
      case 'payment_intent.succeeded':
        await handlePaymentSucceeded(event.data.object as Stripe.PaymentIntent)
        break

      case 'customer.subscription.created':
        await handleSubscriptionCreated(event.data.object as Stripe.Subscription)
        break

      case 'customer.subscription.updated':
        await handleSubscriptionUpdated(event.data.object as Stripe.Subscription)
        break

      case 'customer.subscription.deleted':
        await handleSubscriptionCanceled(event.data.object as Stripe.Subscription)
        break

      case 'invoice.payment_succeeded':
        await handleInvoicePaymentSucceeded(event.data.object as Stripe.Invoice)
        break

      case 'invoice.payment_failed':
        await handleInvoicePaymentFailed(event.data.object as Stripe.Invoice)
        break

      default:
        console.log(`Unhandled event type: ${event.type}`)
    }

    return NextResponse.json({ received: true })
  } catch (error) {
    console.error('Webhook error:', error)
    return NextResponse.json(
      { error: 'Webhook processing failed' },
      { status: 500 }
    )
  }
}

async function handlePaymentSucceeded(paymentIntent: Stripe.PaymentIntent) {
  const supabase = createServerClient()

  try {
    // Get customer info
    const customer = paymentIntent.customer as string
    const amount = paymentIntent.amount / 100 // Convert from cents

    // Find user by Stripe customer ID
    const { data: profile } = await supabase
      .from('profiles')
      .select('*')
      .eq('stripe_customer_id', customer)
      .single()

    if (profile) {
      // Track revenue event
      await trackRevenueEvent(
        profile.id,
        'payment_succeeded',
        amount,
        {
          payment_intent_id: paymentIntent.id,
          currency: paymentIntent.currency,
          payment_method: paymentIntent.payment_method
        }
      )

      console.log(`Payment succeeded: $${amount} for user ${profile.id}`)
    }
  } catch (error) {
    console.error('Error handling payment succeeded:', error)
  }
}

async function handleSubscriptionCreated(subscription: Stripe.Subscription) {
  const supabase = createServerClient()

  try {
    const customer = subscription.customer as string
    const priceId = subscription.items.data[0]?.price.id

    // Determine subscription tier from price ID
    let tier = 'free'
    switch (priceId) {
      case process.env.STRIPE_PRICE_BASIC:
        tier = 'basic'
        break
      case process.env.STRIPE_PRICE_PRO:
        tier = 'pro'
        break
      case process.env.STRIPE_PRICE_ENTERPRISE:
        tier = 'enterprise'
        break
    }

    // Update user profile
    const { data: profile } = await supabase
      .from('profiles')
      .update({
        subscription_tier: tier,
        stripe_subscription_id: subscription.id,
        api_calls_limit: getAPILimitForTier(tier)
      })
      .eq('stripe_customer_id', customer)
      .select()
      .single()

    if (profile) {
      // Track subscription event
      await trackRevenueEvent(
        profile.id,
        'subscription_created',
        subscription.items.data[0]?.price.unit_amount ? subscription.items.data[0].price.unit_amount / 100 : 0,
        {
          subscription_id: subscription.id,
          tier,
          price_id: priceId
        }
      )

      console.log(`Subscription created: ${tier} for user ${profile.id}`)
    }
  } catch (error) {
    console.error('Error handling subscription created:', error)
  }
}

async function handleSubscriptionUpdated(subscription: Stripe.Subscription) {
  const supabase = createServerClient()

  try {
    const customer = subscription.customer as string

    // Update subscription status
    const { error } = await supabase
      .from('profiles')
      .update({
        stripe_subscription_status: subscription.status
      })
      .eq('stripe_customer_id', customer)

    if (error) {
      console.error('Error updating subscription:', error)
    } else {
      console.log(`Subscription updated for customer ${customer}`)
    }
  } catch (error) {
    console.error('Error handling subscription updated:', error)
  }
}

async function handleSubscriptionCanceled(subscription: Stripe.Subscription) {
  const supabase = createServerClient()

  try {
    const customer = subscription.customer as string

    // Downgrade to free tier
    const { data: profile } = await supabase
      .from('profiles')
      .update({
        subscription_tier: 'free',
        stripe_subscription_id: null,
        stripe_subscription_status: 'canceled',
        api_calls_limit: 100 // Free tier limit
      })
      .eq('stripe_customer_id', customer)
      .select()
      .single()

    if (profile) {
      // Track cancellation event
      await trackRevenueEvent(
        profile.id,
        'subscription_canceled',
        0,
        {
          subscription_id: subscription.id,
          canceled_at: new Date().toISOString()
        }
      )

      console.log(`Subscription canceled for user ${profile.id}`)
    }
  } catch (error) {
    console.error('Error handling subscription canceled:', error)
  }
}

async function handleInvoicePaymentSucceeded(invoice: Stripe.Invoice) {
  const supabase = createServerClient()

  try {
    const customer = invoice.customer as string
    const amount = invoice.amount_paid / 100

    // Find user and track revenue
    const { data: profile } = await supabase
      .from('profiles')
      .select('*')
      .eq('stripe_customer_id', customer)
      .single()

    if (profile) {
      await trackRevenueEvent(
        profile.id,
        'invoice_payment_succeeded',
        amount,
        {
          invoice_id: invoice.id,
          subscription_id: invoice.subscription,
          currency: invoice.currency
        }
      )

      console.log(`Invoice payment succeeded: $${amount} for user ${profile.id}`)
    }
  } catch (error) {
    console.error('Error handling invoice payment succeeded:', error)
  }
}

async function handleInvoicePaymentFailed(invoice: Stripe.Invoice) {
  const supabase = createServerClient()

  try {
    const customer = invoice.customer as string

    // Find user and log failed payment
    const { data: profile } = await supabase
      .from('profiles')
      .select('*')
      .eq('stripe_customer_id', customer)
      .single()

    if (profile) {
      await trackRevenueEvent(
        profile.id,
        'invoice_payment_failed',
        0,
        {
          invoice_id: invoice.id,
          subscription_id: invoice.subscription,
          failure_reason: invoice.last_finalization_error?.message || 'Unknown'
        }
      )

      console.log(`Invoice payment failed for user ${profile.id}`)
    }
  } catch (error) {
    console.error('Error handling invoice payment failed:', error)
  }
}

function getAPILimitForTier(tier: string): number {
  switch (tier) {
    case 'basic':
      return 1000
    case 'pro':
      return 10000
    case 'enterprise':
      return 100000
    default:
      return 100 // Free tier
  }
}'''

