dashboard_api_ts = '''import { NextRequest, NextResponse } from 'next/server'
import { createServerClient } from '@/lib/supabase'
import { getRevenueStats, getAPIUsageStats } from '@/lib/supabase'

export async function GET(request: NextRequest) {
  try {
    const supabase = createServerClient()

    // Get user from auth header
    const authHeader = request.headers.get('authorization')
    if (!authHeader?.startsWith('Bearer ')) {
      return NextResponse.json(
        { error: 'Missing or invalid authorization header' },
        { status: 401 }
      )
    }

    const userId = authHeader.replace('Bearer ', '')

    // Verify user exists
    const { data: user, error: userError } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .single()

    if (userError || !user) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      )
    }

    // Get revenue stats
    const revenueStats = await getRevenueStats(userId)

    // Get API usage stats
    const usageStats = await getAPIUsageStats(userId)

    // Calculate growth rate (mock calculation for now)
    const previousMonthRevenue = revenueStats.monthlyRevenue * 0.8 // Mock 20% growth
    const growthRate = previousMonthRevenue > 0 
      ? ((revenueStats.monthlyRevenue - previousMonthRevenue) / previousMonthRevenue) * 100 
      : 0

    // Get active users count (mock data)
    const activeUsers = Math.floor(Math.random() * 1000) + 500

    const dashboardData = {
      totalRevenue: revenueStats.totalRevenue,
      monthlyRevenue: revenueStats.monthlyRevenue,
      apiCalls: usageStats.totalRequests,
      activeUsers,
      conversionRate: usageStats.successRate,
      growthRate,
      subscription_tier: user.subscription_tier,
      api_calls_used: user.api_calls_used,
      api_calls_limit: user.api_calls_limit
    }

    return NextResponse.json(dashboardData)
  } catch (error) {
    console.error('Dashboard API error:', error)
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    )
  }
}'''

