    let databaseHealthy = true

    try {
      await supabase.from('profiles').select('id').limit(1)
    } catch (error) {
      console.error('Database health check failed:', error)
      databaseHealthy = false
    }

    // Check HF Spaces connection (mock for now)
    let hfSpacesHealthy = true
    try {
      const hfResponse = await fetch(process.env.NEXT_PUBLIC_HF_SPACES_URL + '/health', {
        signal: AbortSignal.timeout(5000)
      })
      hfSpacesHealthy = hfResponse.ok
    } catch (error) {
      console.error('HF Spaces health check failed:', error)
      hfSpacesHealthy = false
    }

    const responseTime = Date.now() - startTime

    const health = {
      status: (databaseHealthy && hfSpacesHealthy) ? 'healthy' : 'degraded',
      services: {
        database: databaseHealthy,
        huggingface: hfSpacesHealthy,
        api: true
      },
      responseTime,
      timestamp: new Date().toISOString(),
      version: '3.0.0'
