# Service Worker for PWA functionality
service_worker_js = '''// OASIS v3 Service Worker
// Provides offline functionality and caching for mobile-first experience

const CACHE_NAME = 'oasis-v3-cache-v1.0.0'
const RUNTIME = 'oasis-v3-runtime'

// Critical files that should always be cached
const PRECACHE_URLS = [
  '/',
  '/dashboard',
  '/chat',
  '/offline',
  '/manifest.json'
]

// Install event - cache critical resources
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        console.log('Service Worker: Caching critical files')
        return cache.addAll(PRECACHE_URLS)
      })
      .then(() => {
        console.log('Service Worker: Installed successfully')
        return self.skipWaiting()
      })
  )
})

// Activate event - clean up old caches
self.addEventListener('activate', event => {
  const currentCaches = [CACHE_NAME, RUNTIME]

  event.waitUntil(
    caches.keys().then(cacheNames => {
      return cacheNames.filter(cacheName => !currentCaches.includes(cacheName))
    }).then(cachesToDelete => {
      return Promise.all(cachesToDelete.map(cacheToDelete => {
        console.log('Service Worker: Deleting old cache', cacheToDelete)
        return caches.delete(cacheToDelete)
      }))
    }).then(() => {
      console.log('Service Worker: Activated successfully')
      return self.clients.claim()
    })
  )
})

// Fetch event - serve from cache, fallback to network
self.addEventListener('fetch', event => {
  // Skip cross-origin requests and non-GET requests
  if (event.request.url.startsWith(self.location.origin) && event.request.method === 'GET') {
    event.respondWith(
      caches.match(event.request).then(cachedResponse => {
        if (cachedResponse) {
          // Serve from cache
          return cachedResponse
        }

        return caches.open(RUNTIME).then(cache => {
          return fetch(event.request).then(response => {
            // Only cache successful responses
            if (response.status === 200) {
              // Cache API responses for limited time
              if (event.request.url.includes('/api/')) {
                // Cache API responses for 5 minutes
                const responseToCache = response.clone()
                const cacheControl = 'max-age=300'
                const modifiedResponse = new Response(responseToCache.body, {
                  status: responseToCache.status,
                  statusText: responseToCache.statusText,
                  headers: {
                    ...responseToCache.headers,
                    'Cache-Control': cacheControl
                  }
                })
                cache.put(event.request, modifiedResponse)
              } else {
                // Cache other resources normally
                cache.put(event.request, response.clone())
              }
            }
            return response
          }).catch(() => {
            // If network fails, try to serve offline page for navigation requests
            if (event.request.mode === 'navigate') {
              return caches.match('/offline')
            }
            // For other resources, return a basic error response
            return new Response('Offline', { 
              status: 503, 
              statusText: 'Service Unavailable' 
            })
          })
        })
      })
    )
  }
})

// Background sync for when connection is restored
self.addEventListener('sync', event => {
  if (event.tag === 'sync-ai-requests') {
    event.waitUntil(syncAIRequests())
  }
})

// Push notification handling
self.addEventListener('push', event => {
  if (event.data) {
    const data = event.data.json()
    const title = data.title || 'OASIS v3 Notification'
    const options = {
      body: data.body || 'You have a new update from OASIS v3',
      icon: '/icon-192x192.png',
      badge: '/icon-96x96.png',
      tag: data.tag || 'oasis-notification',
      data: data.url || '/',
      actions: [
        {
          action: 'open',
          title: 'Open App',
          icon: '/icon-96x96.png'
        },
        {
          action: 'dismiss',
          title: 'Dismiss'
        }
      ]
    }

    event.waitUntil(
      self.registration.showNotification(title, options)
    )
  }
})

// Handle notification clicks
self.addEventListener('notificationclick', event => {
  event.notification.close()

  if (event.action === 'open' || !event.action) {
    const url = event.notification.data || '/'
    event.waitUntil(
      clients.openWindow(url)
    )
  }
})

// Sync AI requests when back online
async function syncAIRequests() {
  try {
    // Get pending requests from IndexedDB
    const pendingRequests = await getPendingAIRequests()

    for (const request of pendingRequests) {
      try {
        const response = await fetch('/api/ai/process', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(request)
        })

        if (response.ok) {
          await removePendingRequest(request.id)
          console.log('Synced AI request:', request.id)
        }
      } catch (error) {
        console.error('Failed to sync AI request:', request.id, error)
      }
    }
  } catch (error) {
    console.error('Background sync failed:', error)
  }
}

// Helper functions for IndexedDB operations
async function getPendingAIRequests() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('oasis-v3-db', 1)

    request.onerror = () => reject(request.error)
    request.onsuccess = () => {
      const db = request.result
      const transaction = db.transaction(['pending_requests'], 'readonly')
      const store = transaction.objectStore('pending_requests')
      const getAll = store.getAll()

      getAll.onsuccess = () => resolve(getAll.result)
      getAll.onerror = () => reject(getAll.error)
    }

    request.onupgradeneeded = () => {
      const db = request.result
      if (!db.objectStoreNames.contains('pending_requests')) {
        db.createObjectStore('pending_requests', { keyPath: 'id' })
      }
    }
  })
}

async function removePendingRequest(id) {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('oasis-v3-db', 1)

    request.onsuccess = () => {
      const db = request.result
      const transaction = db.transaction(['pending_requests'], 'readwrite')
      const store = transaction.objectStore('pending_requests')
      const deleteRequest = store.delete(id)

      deleteRequest.onsuccess = () => resolve()
      deleteRequest.onerror = () => reject(deleteRequest.error)
    }
  })
}

